<?php
namespace MarinePortal\Database;
use PDO;
class Connection { private static ?self $instance=null; public PDO $pdo; public string $driver; public static function getInstance(): self { if(self::$instance) return self::$instance; $cfg=require ROOT.'/config.php'; $dbCfg=$cfg['database']; $driver=$dbCfg['driver']; self::$instance=new self($driver,$dbCfg[$driver] ?? []); return self::$instance; } public function __construct(string $driver, array $cfg){ $this->driver=$driver; $dsn=$this->buildDsn($driver,$cfg); $user=$cfg['username']??null; $pass=$cfg['password']??null; $opts=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]; if($driver==='sqlite'){ $user=null; $pass=null; if(!file_exists($cfg['path'])){ @touch($cfg['path']); } } $this->pdo=new PDO($dsn,$user,$pass,$opts); } private function buildDsn(string $driver, array $cfg): string { return match($driver){ 'mysql' => "mysql:host={$cfg['host']};port={$cfg['port']};dbname={$cfg['database']};charset={$cfg['charset']}", 'pgsql' => "pgsql:host={$cfg['host']};port={$cfg['port']};dbname={$cfg['database']}", 'sqlite' => "sqlite:{$cfg['path']}", default => throw new \Exception("Unsupported driver $driver") }; } }
